      "paragraph_starts": [
        {"text": "phénoménologie par excellence ; la thèse inverse, celle d’une véritable « catastrophe » produite", "continues_from_previous": false, "continues_to_next": false},
        {"text": "Si Courtine a eu le mérite de poser la question avec une", "continues_from_previous": false, "continues_to_next": false},
